// Filter pesanan hari ini
const today = new Date().toISOString().slice(0, 10);
const allOrders = $('Ambil Semua Pesanan Hari Ini').all();
const allReservations = $('Ambil Reservasi Hari Ini').all();

const todayOrders = allOrders.filter(item => {
  const orderTime = item.json.order_time || '';
  return orderTime.startsWith(today);
});

const todayReservations = allReservations.filter(item => {
  const createdAt = item.json.created_at || '';
  return createdAt.startsWith(today);
});

// Hitung statistik
const totalOrders = todayOrders.length;
const dineIn = todayOrders.filter(o => o.json.order_type === 'dine-in').length;
const takeAway = todayOrders.filter(o => o.json.order_type === 'take-away').length;
const totalReservations = todayReservations.length;

// Rekap pesanan per item (simple text analysis)
const itemCount = {};
todayOrders.forEach(o => {
  const items = (o.json.items || '').toLowerCase();
  ['ayam taliwang', 'sate rembiga', 'plecing kangkung', 'beberuk terong', 'nasi balap', 'ikan bakar', 'es kelapa'].forEach(item => {
    if (items.includes(item)) {
      itemCount[item] = (itemCount[item] || 0) + 1;
    }
  });
});

// Urutkan menu terlaris
const sortedItems = Object.entries(itemCount)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5);

const menuTerlaris = sortedItems.length > 0
  ? sortedItems.map((e, i) => `${i+1}. ${e[0].replace(/\b\w/g, c => c.toUpperCase())}: ${e[1]}x`).join('\n')
  : 'Tidak ada data';

// Daftar pesanan hari ini
const orderList = todayOrders.length > 0
  ? todayOrders.map(o => `- ${o.json.order_id} | ${o.json.customer_name} | ${o.json.order_type}`).join('\n')
  : 'Tidak ada pesanan';

// Format tanggal Indonesia
const tanggal = new Date().toLocaleDateString('id-ID', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Makassar'
});

const laporan = `*LAPORAN HARIAN*
*${$env.RESTAURANT_NAME}*
${tanggal}

*RINGKASAN PESANAN*
Total Pesanan: ${totalOrders}
Makan di Tempat: ${dineIn}
Bawa Pulang: ${takeAway}

*MENU TERLARIS*
${menuTerlaris}

*RESERVASI BARU*
Total Reservasi: ${totalReservations}

*DAFTAR PESANAN*
${orderList}

_Laporan otomatis pukul 22:00 WITA_`;

return [{ json: { laporan, totalOrders, totalReservations } }];
